"""Pricing helpers. quote_total and invoice_total share _apply_rounding (INC-3355).

INC-3355: the invoice path had a HALF_UP copy that diverged from the HALF_EVEN quote on every .5 case,
so a quote and its invoice disagreed by a cent. Both totals now route through one contract HALF_EVEN
helper, so quote and invoice always agree.
"""


def _apply_rounding(tenth_cents):
    """Contract HALF_EVEN (banker's) rounding shared by quote_total and invoice_total (INC-3355)."""
    base, rem = tenth_cents // 10, tenth_cents % 10
    if rem < 5:
        return base
    if rem > 5:
        return base + 1
    return base + 1 if base % 2 == 1 else base           # HALF_EVEN (contract)


def quote_total(order):
    return _apply_rounding(sum(order))


def invoice_total(order):
    return _apply_rounding(sum(order))

